// returns the index of the chosen action (argmax of the output layer)
static int crawler_medium_act(const float *obs) {
  float a[64], c[64];
  for (int i = 0; i < 27; i++) a[i] = (obs[i] - crawler_medium_mu[i]) / crawler_medium_sd[i];
  for (int o = 0; o < 64; o++) {
    float s = crawler_medium_b0[o];
    for (int k = 0; k < 27; k++) s += crawler_medium_W0[o][k] * a[k];
    c[o] = tanhf(s);
  }
  for (int o = 0; o < 64; o++) a[o] = c[o];
  for (int o = 0; o < 64; o++) {
    float s = crawler_medium_b1[o];
    for (int k = 0; k < 64; k++) s += crawler_medium_W1[o][k] * a[k];
    c[o] = tanhf(s);
  }
  for (int o = 0; o < 64; o++) a[o] = c[o];
  for (int o = 0; o < 5; o++) {
    float s = crawler_medium_b2[o];
    for (int k = 0; k < 64; k++) s += crawler_medium_W2[o][k] * a[k];
    c[o] = s;
  }
  for (int o = 0; o < 5; o++) a[o] = c[o];
  int best = 0; for (int o = 1; o < 5; o++) if (a[o] > a[best]) best = o;
  return best;
}
